import { NgModule } from '@angular/core';
import ConfigService from './services/config/config.service';
import { AuthService } from './services/auth/auth.service';
import { LoggedInHeaderComponent } from './components/logged-in-layout/logged-in-header/header.component';
import { LoggedOutHeaderComponent } from './components/logged-out-layout/logged-out-header/header.component';
import { LoggedInStructureComponent } from './components/logged-in-layout/logged-in-structure/structure.component';
import { LoggedOutStructureComponent } from './components/logged-out-layout/logged-out-structure/structure.component';
import { Web3ProviderService } from './services/web3/web3-provider.service';
import { provideHttpClient, withInterceptors } from '@angular/common/http';
import { RouterModule } from '@angular/router';
import { CommonModule } from '@angular/common';

import { MatIconModule } from '@angular/material/icon';
import { MatButtonModule } from '@angular/material/button';
import { MatToolbarModule } from '@angular/material/toolbar';
import { appInitializer } from '../initializers/app.initializer';
import { loggingInterceptor } from './interceptors/logging.interceptor';
import { authInterceptor } from './interceptors/auth.interceptor';
import { LoggedOutFooterComponent } from './components/logged-out-layout/logged-out-footer/logged-out-footer.component';

/*
The core functions, services, and models shared globally across the application and
didn’t have any relation to the feature module must be a part of the core module.
The singleton services should be implemented here that have to have one and only one instance per application. 
The Module contains an Authentication service and static components like 
 - the header, 
 - footer, 
 - navbar, 
  - sidebar, 
  - interceptors, 
  - guards, 
  - constants, 
  - enums, 
  - utils, 
  - and universal models.

One must import the core module only in the app root module. 
Other modules must not import the core module.
*/
@NgModule({
  imports: [
    CommonModule,
    RouterModule,
    MatIconModule,
    MatButtonModule,
    MatToolbarModule,
  ],
  providers: [
    AuthService,
    ConfigService,
    appInitializer,
    Web3ProviderService,
    provideHttpClient(withInterceptors([loggingInterceptor, authInterceptor])),
  ],
  declarations: [
    LoggedInHeaderComponent,
    LoggedOutFooterComponent,
    LoggedOutHeaderComponent,
    LoggedInStructureComponent,
    LoggedOutStructureComponent,
  ],
  exports: [
    LoggedInHeaderComponent,
    LoggedOutFooterComponent,
    LoggedOutHeaderComponent,
    LoggedInStructureComponent,
    LoggedOutStructureComponent,
  ],
})
export class AppCoreModule {}
