import { CommonModule } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';
import { MatInputModule } from '@angular/material/input';
import { MatButtonModule } from '@angular/material/button';
import { MatChipsModule } from '@angular/material/chips';
import { AfterContentInit, Component, forwardRef, Input } from '@angular/core';
import {
  AbstractControl,
  ControlValueAccessor,
  FormGroup,
  NG_VALUE_ACCESSOR,
  ReactiveFormsModule,
  TouchedChangeEvent,
} from '@angular/forms';
import { filter } from 'rxjs/operators';

@Component({
  selector: 'object-box',
  styleUrl: './object-box.component.scss',
  templateUrl: './object-box.component.html',
  providers: [
    {
      multi: true,
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => ObjectBoxComponent),
    },
  ],
})
export class ObjectBoxComponent
  implements ControlValueAccessor, AfterContentInit
{
  @Input() formGroup!: FormGroup;
  @Input() displayField!: string;

  values: any[] = [];
  editingItem: any = undefined;

  get editMode() {
    return !!this.editingItem;
  }

  private _onTouched!: () => void;
  private _onChange!: (value: any) => void;

  constructor() {}

  ngAfterContentInit() {
    this.formGroup.events
      .pipe(filter((event) => event instanceof TouchedChangeEvent))
      .subscribe({
        next: (evt) => {
          if (evt.touched) this._onTouched();
        },
      });
  }

  writeValue(values: any[]): void {
    if (!Array.isArray(values)) return;
    this.values = values ?? [];
  }

  registerOnChange(fn: any): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    for (const name in this.formGroup?.controls) {
      const ctrl: AbstractControl<any, any> = this.formGroup.controls[name];
      if (isDisabled) ctrl.disable({ onlySelf: true, emitEvent: false });
    }
  }

  resetControls() {
    this.formGroup?.reset();
  }

  addItem() {
    const item = this.formGroup.value;
    const existing =
      this.values?.length > 0 &&
      this.values.find((v) => v[this.displayField] === item[this.displayField]);
    if (existing) {
      this.resetControls();
      return;
    }

    this.values.push({ ...item });
    this._onChange(this.values);
    this.resetControls();
  }

  enterEditMode(item: any) {
    const obj = { ...item };
    this.editingItem = obj;
    this.formGroup.setValue(obj);
  }

  exitEditMode() {
    this.editingItem = undefined;
    this.resetControls();
  }

  updateItem(): void {
    const updatedValue = this.formGroup.value;
    const idx = this.values.findIndex(
      (v) => v[this.displayField] == this.editingItem[this.displayField]
    );
    if (idx < 0) return;

    const existing = this.values?.find(
      (v) => v[this.displayField] === updatedValue[this.displayField]
    );
    if (existing) {
      this.resetControls();
      return;
    }

    this.values[idx] = updatedValue;
    this._onChange(this.values);
    this.editingItem = undefined;
    this.resetControls();
  }

  removeItem(item: any) {
    const idx = this.values?.findIndex(
      (v) => v[this.displayField] === item[this.displayField]
    );
    if (idx < 0) return;

    this.values.splice(idx, 1);
    if (this._onChange) this._onChange(this.values);
  }
}
