import { Component, signal, WritableSignal } from '@angular/core';
import {
  FormBuilder,
  FormControl,
  FormGroup,
  Validators,
} from '@angular/forms';
import { TokenFactoryService } from '../services/token-factory.service';
import { Web3ProviderService } from 'src/app/core/services/web3/web3-provider.service';
import { GameService } from '../services/game.service';
import {
  AttributeTarget,
  AttributeType,
  HookType,
} from 'src/app/dto/enum/user_type';
import {
  AttributeDTO,
  NewGameRequestDTO,
  NewGameResponseDTO,
} from 'src/app/dto/game/game.dto';

@Component({
  selector: 'app-new-game',
  templateUrl: './new-game.component.html',
  styleUrls: ['./new-game.component.scss'],
})
export class NewGameComponent {
  form!: FormGroup;
  hookForm!: FormGroup;
  matchAttrForm!: FormGroup;
  playerAttrForm!: FormGroup;
  serversForm!: FormGroup;

  availableVerbs: string[] = ['GET', 'POST'];
  availableHooks: string[] = Object.values(HookType);
  availableAttrTypes: string[] = Object.values(AttributeType);
  availableAttrTargets: string[] = Object.values(AttributeTarget);

  get basicInfoSection(): FormGroup {
    return this.form.controls['basicInfoSection'] as FormGroup;
  }

  get providerSection(): FormGroup {
    return this.form.controls['providerSection'] as FormGroup;
  }

  get infraSection(): FormGroup {
    return this.form.controls['infraSection'] as FormGroup;
  }

  get matchSection(): FormGroup {
    return this.form.controls['matchSection'] as FormGroup;
  }

  get playerSection(): FormGroup {
    return this.form.controls['playerSection'] as FormGroup;
  }

  get gameTokenSection(): FormGroup {
    return this.form.controls['gameTokenSection'] as FormGroup;
  }

  get integrationSection(): FormGroup {
    return this.form.controls['integrationSection'] as FormGroup;
  }

  constructor(
    private readonly _gameService: GameService,
    private readonly _formBuilder: FormBuilder,
    private readonly _provider: Web3ProviderService,
    private readonly _tokenFactoryService: TokenFactoryService
  ) {
    this.hookForm = _formBuilder.group({
      url: new FormControl('', [Validators.required]),
      type: new FormControl('', [Validators.required]),
      verb: new FormControl('', [Validators.required]),
    });

    this.matchAttrForm = _formBuilder.group({
      type: new FormControl('', [Validators.required]),
      name: new FormControl('', [Validators.required]),
      description: new FormControl('', [Validators.required]),
    });

    this.playerAttrForm = _formBuilder.group({
      type: new FormControl('', [Validators.required]),
      name: new FormControl('', [Validators.required]),
      description: new FormControl('', [Validators.required]),
    });

    this.serversForm = _formBuilder.group({
      dns: new FormControl('', [Validators.required]),
      name: new FormControl('', [Validators.required]),
    });

    // TODO: colocar os validadores
    this.form = this._formBuilder.group({
      accounts: [[], []],
      matchSection: this._formBuilder.group({
        matchTypes: ['', []],
        attributes: [[], []],
      }),
      playerSection: this._formBuilder.group({
        attributes: [[], []],
      }),
      gameTokenSection: this._formBuilder.group({
        name: ['', [Validators.required]],
        symbol: ['', [Validators.required]],
        decimals: [18, [Validators.required]],
        initialSupply: [undefined, [Validators.required]],
      }),
      basicInfoSection: this._formBuilder.group({
        name: ['', []],
        tags: [[], []],
        allowCrossplay: [false, []],
        allowPlatformVoting: [false, []],
      }),
      infraSection: this._formBuilder.group({
        servers: [[], []],
        throughput: ['', []],
        maintenceTimeCronExpr: ['', []],
      }),
      providerSection: this._formBuilder.group({
        isPSNEnabled: [false, []],
        isEpicEnabled: [false, []],
        isXboxEnabled: [false, []],
        isSteamEnabled: [false, []],
      }),
      integrationSection: this._formBuilder.group({
        hooks: [[], []],
      }),
    });
  }

  async ngOnInit() {}

  async connect() {
    this.form.controls['accounts'].setValue(
      await this._tokenFactoryService.connect()
    );
  }

  async createGame(): Promise<void> {
    const { hooks } = this.integrationSection.value;
    const { attributes: playerAttributes } = this.playerSection.value;
    const { matchTypes, attributes: matchAttributes } = this.matchSection.value;

    const { name, tags, allowCrossplay, allowPlatformVoting } =
      this.basicInfoSection.value;

    const { servers, throughput, maintenceTimeCronExpr } =
      this.infraSection.value;

    const { isPSNEnabled, isEpicEnabled, isXboxEnabled, isSteamEnabled } =
      this.providerSection.value;

    const {
      symbol,
      decimals,
      initialSupply,
      name: tokenName,
    } = this.gameTokenSection.value;

    const payload: NewGameRequestDTO = {
      name,
      hooks,
      allowCrossplay,
      isEpicEnabled,
      isPSNEnabled,
      isSteamEnabled,
      isXboxEnabled,
      matchTypes,
      servers,
      tags,
      allowPlatformVoting,
      throughput,
      maintenceTimeCronExpr,
      attributes: [...matchAttributes, ...playerAttributes],
      gameToken: {
        symbol,
        decimals,
        initialSupply,
        name: tokenName,
      },
    };

    this._gameService
      .create(payload)
      .then((response: NewGameResponseDTO) => {
        return this._tokenFactoryService.deployToken({
          ...response.signatureResult,
        });
      })
      .then(() => {
        // mostrar sucesso ao criar token
      })
      .catch((err) => {
        // TODO: tratar
      });
  }

  // Apagar após testes
  async loadFakeGame(): Promise<void> {
    this._gameService
      .getFakeGame()
      .then((response: NewGameResponseDTO) => {
        const {
          name,
          tags,
          hooks,
          servers,
          matchTypes,
          attributes,
          throughput,
          isPSNEnabled,
          isEpicEnabled,
          isXboxEnabled,
          allowCrossplay,
          isSteamEnabled,
          maintenceTimeCronExpr,
          allowPlatformVoting,
          gameToken,
        } = response;

        const matchAttr = attributes.filter(
          (a) => a.target === AttributeTarget.Match
        );
        const playerAttr = attributes.filter(
          (a) => a.target === AttributeTarget.Player
        );

        // AJUDA: embora as linhas acimas estejam preenchidas
        // a linha abaixo nao surte efeito, o form nao preenche
        // TALVEZ TA FALTANDO PREENCHER ALGUM CAMPO
        this.form.patchValue({
          matchSection: {
            matchTypes,
            attributes: matchAttr,
          },
          playerSection: {
            attributes: playerAttr,
          },
          gameTokenSection: {
            name: gameToken.name,
            symbol: gameToken.symbol,
            decimals: gameToken.decimals,
            initialSupply: gameToken.initialSupply,
          },
          basicInfoSection: {
            name,
            tags,
            allowCrossplay,
            allowPlatformVoting,
          },
          infraSection: {
            servers,
            throughput,
            maintenceTimeCronExpr,
          },
          providerSection: {
            isPSNEnabled,
            isEpicEnabled,
            isXboxEnabled,
            isSteamEnabled,
          },
          integrationSection: {
            hooks,
          },
        });
      })
      .catch((err) => {
        // TODO: tratar
      });
  }
}
