// https://angular.dev/guide/http/interceptors
import { HttpEvent, HttpHandlerFn, HttpRequest } from '@angular/common/http';
import { Observable } from 'rxjs';
import { LoginResponseDTO } from 'src/app/dto/auth/auth.dto';

const userInfoStorageKey = 'USER_INFO';

export function authInterceptor(
  req: HttpRequest<unknown>,
  next: HttpHandlerFn
): Observable<HttpEvent<unknown>> {
  const rawUserInfo = localStorage.getItem(userInfoStorageKey);
  const userInfo: LoginResponseDTO = JSON.parse(rawUserInfo ?? '{ }');

  if (userInfo.accessToken) {
    const cloneReq = req.clone({
      setHeaders: { Authorization: `Bearer ${userInfo.accessToken}` },
    });
    return next(cloneReq);
  }

  // TODO: implementar refresh e retries
  return next(req);
}
