import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { AuthService } from 'src/app/core/services/auth/auth.service';
import { Web3ProviderService } from 'src/app/core/services/web3/web3-provider.service';
import { UserType } from 'src/app/dto/enum/user_type';

@Component({
  selector: 'app-signup',
  templateUrl: './signup.component.html',
  styleUrls: ['./signup.component.scss'],
})
export class SignupPageComponent {
  signupError?: string;
  stepOneForm!: FormGroup;
  stepTwoForm!: FormGroup;
  signatureForm!: FormGroup;

  constructor(
    private fb: FormBuilder,
    private readonly _router: Router,
    private readonly _authService: AuthService,
    private readonly _web3Provider: Web3ProviderService
  ) {
    this.stepOneForm = this.fb.group({
      wallet: ['', [Validators.required]],
      profile: ['', [Validators.required]],
    });

    this.stepTwoForm = this.fb.group({
      taxId: ['', [Validators.required]],
      email: ['', [Validators.required, Validators.email]],
      name: ['', [Validators.required, Validators.minLength(2)]],
    });

    this.signatureForm = this.fb.group({
      nonce: ['', [Validators.required]],
      message: ['', [Validators.required]],
      timestamp: ['', [Validators.required]],
      signature: ['', [Validators.required]],
    });
  }

  async connectWallet(event: any): Promise<void> {
    try {
      const accounts = await this._web3Provider.connect();
      this.stepOneForm.controls['wallet'].setValue(accounts[0]?.toUpperCase());
    } catch (error: any) {
      console.error('Wallet connection error:', error);
    }
  }

  async sign(): Promise<void> {
    try {
      const { message, nonce, timestamp } =
        await this._authService.getSignupMessage();

      const signature = await this._web3Provider.signPersonal(message);

      this.signatureForm.setValue({
        nonce,
        message,
        timestamp,
        signature,
      });
    } catch (e) {
      // TODO: tratar erro
      throw e;
    }
  }

  async submit(): Promise<void> {
    try {
      const { profile, wallet } = this.stepOneForm.value;
      const { message, nonce, timestamp, signature } = this.signatureForm.value;

      const createdPlayer = await this._authService.createPlayer(
        {
          ...this.stepTwoForm.value,
          userType: profile,
          wallet: wallet?.toUpperCase(),
        },
        { message, nonce, timestamp, signature }
      );

      // TODO: algum toaster
      this._router.navigateByUrl('/login');
    } catch (e) {
      this.signupError = '';
    }
  }
}
