import { Component, forwardRef, Input, OnInit } from '@angular/core';
import {
  FormControl,
  ControlValueAccessor,
  NG_VALUE_ACCESSOR,
  NG_VALIDATORS,
  FormBuilder,
} from '@angular/forms';

@Component({
  selector: 'app-tag-box',
  // standalone: true,
  // imports: [],
  templateUrl: './tag-box.component.html',
  styleUrl: './tag-box.component.scss',
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => TagBoxComponent),
      multi: true,
    },
    // {
    //   provide: NG_VALIDATORS,
    //   useExisting: forwardRef(() => TagBoxComponent),
    //   multi: true,
    // },
  ],
})
export class TagBoxComponent implements ControlValueAccessor, OnInit {
  @Input() label = 'Items';
  @Input() placeholder = 'Items';
  items: string[] = [];
  control: FormControl = new FormControl();

  ngOnInit(): void {}

  writeValue(value: any): void {
    this.items = value || [];
  }

  registerOnChange(fn: any): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    isDisabled ? this.control.disable() : this.control.enable();
  }

  addItem(event: any): void {
    const input = event.input;
    const value = event.value;

    const exists = this.items.indexOf(value) >= 0;
    if (!exists) {
      this.items.push(value);
      this.onChange(this.items);
    }

    if (input) {
      input.value = '';
    }
  }

  removeItem(Item: string): void {
    const index = this.items.indexOf(Item);
    if (index >= 0) {
      this.items.splice(index, 1);
      this.onChange(this.items);
    }
  }

  private onChange(value: any) {
    // O que devo fazer aqui?
  }

  private onTouched() {
    // O que devo fazer aqui?
  }
}
