import { ethers } from 'ethers';
import { Injectable } from '@angular/core';
import { BrowserProvider, JsonRpcSigner } from 'ethers';
import { EIP712Data } from 'src/app/dto/signature/eip712_data.dto';

// o primeiro argumento do send, pode ser consultado aqui
// EIP-1193: https://eips.ethereum.org/EIPS/eip-1193
@Injectable({
  providedIn: 'root',
})
export class Web3ProviderService extends BrowserProvider {
  private readonly _accounts: string[] = [];

  constructor() {
    super(window.ethereum);
    // Ouve mudanças de conta (mas nao ta evemitindo nao)
    // this._provider.provider.on('accountsChanged', (accounts) => {
    //   debugger;
    //   // emitir algum evento
    //   //console.log('Conta conectada:', accounts[0]);
    // });
  }

  // https://docs.metamask.io/wallet/reference/provider-api/
  // https://stackoverflow.com/questions/70663898/my-dapp-doesnt-detect-when-an-user-change-their-metamask-account
  get connected() {
    return this._accounts.length > 0;
  }

  async chainId(): Promise<number> {
    const chainId = (await this.getNetwork()).chainId;
    return Promise.resolve(Number(chainId));
  }

  async currentAccount() {
    return this.getSigner();
  }

  async connect(): Promise<Array<string>> {
    if (!window.ethereum) {
      return Promise.reject(
        new Error('Please install MetaMask or another wallet extension.')
      );
    }

    return this.send('eth_requestAccounts', [])
      .then((accounts: Array<string>) => {
        this._accounts.push(...(accounts || []));
        return accounts;
      })
      .catch((err) => {
        console.error('Wallet not available', err);
        throw err;
      });
  }

  /*
  async requestPermissions() {
    try {
      return await (window as any).ethereum.request({
        method: 'wallet_requestPermissions',
        params: [{ eth_accounts: {} }],
      });
    } catch (error) {
      console.error('Erro ao solicitar permissões:', error);
    }
  }
  */

  async signTypedData_v4(eip721Data: EIP712Data): Promise<string> {
    try {
      const signer = await this.getSigner();

      const signature: string = await this.send('eth_signTypedData_v4', [
        signer.address,
        eip721Data,
      ]);

      return signature as string;
    } catch (e) {
      console.error(e);
      return Promise.reject(e);
    }
  }

  async signPersonal(message: string): Promise<string> {
    try {
      const signer = await this.getSigner();

      // Converte a string em bytes e depois para hexadecimal
      const hexMessage = ethers.hexlify(ethers.toUtf8Bytes(message));

      const signature: string = await this.send('personal_sign', [
        hexMessage,
        signer.address,
      ]);

      return signature;
    } catch (e) {
      console.error(e);
      return Promise.reject(e);
    }
  }
}
